import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Multi-step Wizard', () => {
  test('Starts on step 1', async () => {
    const { container: root } = render(<App />);
    const ind = root.querySelector('#step-indicator');
if (!ind || !ind.textContent.includes('Step 1 of 3'))
  throw new Error('Expected indicator "Step 1 of 3"');
if (!root.querySelector('#name')) throw new Error('Step 1 should show #name');
if (root.querySelector('#email')) throw new Error('Step 1 should NOT show #email yet');
  });

  test('Next/Back walks through all 3 steps', async () => {
    const { container: root } = render(<App />);
    const inputSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
const name = root.querySelector('#name');
inputSetter.call(name, 'Aanya');
name.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
root.querySelector('#next').click();
await tick();
if (!root.querySelector('#email')) throw new Error('Step 2 should show #email');
const email = root.querySelector('#email');
inputSetter.call(email, 'a@x.com');
email.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
root.querySelector('#next').click();
await tick();
if (!root.querySelector('#role')) throw new Error('Step 3 should show #role');
// Back from step 3 to 2
root.querySelector('#back').click();
await tick();
if (!root.querySelector('#email')) throw new Error('Back from 3 should return to step 2');
root.querySelector('#next').click();
await tick();
if (!root.querySelector('#submit')) throw new Error('Step 3 should show #submit');
  });

  test('Submit shows summary with carried-over values', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#submit').click();
await tick();
const sum = root.querySelector('#summary');
if (!sum) throw new Error('Expected #summary after submit');
const text = sum.textContent;
if (!text.includes('Aanya')) throw new Error('Summary missing name carried from step 1');
if (!text.includes('a@x.com')) throw new Error('Summary missing email carried from step 2');
  });
});
